import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.D7WGirly.js";const g=JSON.parse('{"title":"Goals & Objectives — Overview & Concepts","description":"","frontmatter":{},"headers":[],"relativePath":"goals-01-overview-and-concepts.md","filePath":"goals-01-overview-and-concepts.md"}'),n={name:"goals-01-overview-and-concepts.md"};function r(i,e,l,h,d,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="goals-objectives-—-overview-concepts" tabindex="-1">Goals &amp; Objectives — Overview &amp; Concepts <a class="header-anchor" href="#goals-objectives-—-overview-concepts" aria-label="Permalink to &quot;Goals &amp; Objectives — Overview &amp; Concepts&quot;">​</a></h1><p><em>What goals are, why they exist, and how they connect to the rest of your planning</em></p><hr><h2 id="what-is-a-goal" tabindex="-1">What Is a Goal? <a class="header-anchor" href="#what-is-a-goal" aria-label="Permalink to &quot;What Is a Goal?&quot;">​</a></h2><p>In Lodestone, a Goal is the highest-level thing your team is working toward. Goals sit above Features, Epics, and other Backlog objects in your planning hierarchy — they represent the outcomes you&#39;re organizing work around, not the work itself.</p><p>Goals are deliberately lightweight. Each Goal has a name and an optional description. There are no scoring fields, no evaluation criteria, and no status stages. A Goal&#39;s value comes from what connects to it, not from the data it holds on its own.</p><blockquote><p><strong>Key idea:</strong> Goals are not tasks. They don&#39;t move through a workflow. They serve as anchor points — a way to see, at a glance, which roadmaps, releases, strategies, and backlog objects are contributing to each of your most important objectives.</p></blockquote><hr><h2 id="goals-and-the-object-hierarchy" tabindex="-1">Goals and the Object Hierarchy <a class="header-anchor" href="#goals-and-the-object-hierarchy" aria-label="Permalink to &quot;Goals and the Object Hierarchy&quot;">​</a></h2><p>Goals use your organization&#39;s <strong>top-tier object type</strong> — the type designated in Settings &gt; Taxonomy as the highest level of your hierarchy. This means:</p><ul><li>Goals appear in the Goals &amp; Objectives module as a flat list</li><li>They do not appear in the Backlog&#39;s main list (top-tier objects are excluded there)</li><li>Child objects can be linked to a Goal as parent items, creating the hierarchy that connects planning layers</li></ul><p>If your organization hasn&#39;t configured a top-tier type yet, Goals will appear without typed IDs. Setting a top-tier type in Settings &gt; Taxonomy assigns prefixed IDs (e.g. GOAL-001, OBJ-003) to Goals automatically.</p><hr><h2 id="the-downstream-view" tabindex="-1">The Downstream View <a class="header-anchor" href="#the-downstream-view" aria-label="Permalink to &quot;The Downstream View&quot;">​</a></h2><p>The most useful thing Goals do is aggregate connected work. When a Goal has objects, roadmaps, releases, or strategies linked to it, an expand chevron appears on its row. Clicking the chevron opens the <strong>downstream view</strong>, which shows:</p><table tabindex="0"><thead><tr><th>Section</th><th>What it contains</th></tr></thead><tbody><tr><td>Objects</td><td>Backlog items (Features, Epics, etc.) that have this Goal set as a parent</td></tr><tr><td>Roadmaps</td><td>Roadmaps that include an object with this Goal as a parent</td></tr><tr><td>Releases</td><td>Releases that include an object with this Goal as a parent</td></tr><tr><td>Strategies</td><td>Strategies that reference this Goal&#39;s objects (in bottom-up Strategy mode)</td></tr></tbody></table><p>The downstream view is read-only and refreshes each time you expand it. Each entry is a clickable link — selecting one navigates directly to that roadmap, release, strategy, or backlog item.</p><p>If a Goal has no connected work, the expand chevron does not appear.</p><hr><h2 id="how-goals-connect-to-the-rest-of-lodestone" tabindex="-1">How Goals Connect to the Rest of Lodestone <a class="header-anchor" href="#how-goals-connect-to-the-rest-of-lodestone" aria-label="Permalink to &quot;How Goals Connect to the Rest of Lodestone&quot;">​</a></h2><p>Goals are a connecting layer, not a standalone planning tool. Here is how they interact with each module:</p><table tabindex="0"><thead><tr><th>Module</th><th>Relationship</th></tr></thead><tbody><tr><td>Backlog</td><td>Objects can be linked to a Goal as a parent from the object detail page</td></tr><tr><td>Roadmaps</td><td>Objects with a Goal parent appear in the Goal&#39;s downstream Roadmaps section</td></tr><tr><td>Releases</td><td>Objects with a Goal parent appear in the Goal&#39;s downstream Releases section</td></tr><tr><td>Extracts</td><td>When adding an Extract to the Backlog, AI can suggest a Goal to link the new object to</td></tr><tr><td>Strategy</td><td>Bottom-up strategies surface Goals as grouping context when their child objects are tagged</td></tr></tbody></table><hr><h2 id="who-can-use-goals-objectives" tabindex="-1">Who Can Use Goals &amp; Objectives <a class="header-anchor" href="#who-can-use-goals-objectives" aria-label="Permalink to &quot;Who Can Use Goals &amp; Objectives&quot;">​</a></h2><p>All workspace members (Admin and Builder roles) can view, create, edit, and delete Goals. There are no read-only restrictions for this module.</p><hr><p><em>Next: How-tos &amp; Workflows — creating, editing, and deleting Goals, and reading the downstream view.</em></p>',27)])])}const m=t(n,[["render",r]]);export{g as __pageData,m as default};
